//! Directory resolution abstraction for platform-specific paths.
//!
//! This module provides a trait-based abstraction over directory resolution,
//! enabling dependency injection for testing. The [`BaseDirs`] trait defines
//! the interface for resolving platform-specific directories, while
//! [`SystemBaseDirs`] provides the real implementation using the
//! `directories-next` crate.
//!
//! # Testing
//!
//! In tests, use `MockBaseDirs` (generated by mockall) to avoid writing to
//! the user's actual home directory.

use std::{ffi::OsString, path::PathBuf};

/// Read an absolute path from `variable`, ignoring unset or relative values.
///
/// A relative override would resolve against whatever directory the process
/// happens to run in, which is the working directory rather than the
/// directory the caller meant, so it is discarded here once for every
/// override. `lookup` is the environment: the process in production, a map in
/// tests.
fn absolute_env_path(
    lookup: &impl Fn(&str) -> Option<OsString>,
    variable: &str,
) -> Option<PathBuf> {
    lookup(variable)
        .map(PathBuf::from)
        .filter(|path| path.is_absolute())
}

/// Read an override that only debug builds honour.
///
/// Release builds ignore every such variable, so a stray environment entry
/// cannot relocate a real installation.
fn debug_override(lookup: &impl Fn(&str) -> Option<OsString>, variable: &str) -> Option<PathBuf> {
    if cfg!(debug_assertions) {
        absolute_env_path(lookup, variable)
    } else {
        None
    }
}

/// The directory overrides read from the environment when a
/// [`SystemBaseDirs`] is built.
///
/// Reading them once at construction keeps the resolution methods free of
/// ambient state, so tests supply a lookup instead of mutating the process.
#[derive(Debug, Clone, Default)]
struct DirOverrides {
    /// The XDG bin home directory, if set and absolute.
    #[cfg(unix)]
    xdg_bin_home: Option<PathBuf>,
    /// The data-directory override that debug builds honour.
    ///
    /// Integration tests drive the real binary, which resolves its data
    /// directory from a platform API that ignores `XDG_DATA_HOME` on Windows.
    /// The override lets such a test keep the installation record inside its
    /// own temporary directory. Release builds ignore it, so it cannot
    /// relocate a real install.
    test_data_home: Option<PathBuf>,
    /// The executable-directory override that debug builds honour.
    ///
    /// The bin root has the same portability problem as the data directory:
    /// Windows derives it from the home directory in the profile known
    /// folder, which ignores `HOME` and `XDG_BIN_HOME`. The override lets an
    /// integration test point the binary at a directory it can inspect.
    /// Release builds ignore it, so it cannot relocate a real installation.
    test_executable_home: Option<PathBuf>,
}

impl DirOverrides {
    /// Read every override through `lookup`.
    fn read(lookup: &impl Fn(&str) -> Option<OsString>) -> Self {
        Self {
            #[cfg(unix)]
            xdg_bin_home: absolute_env_path(lookup, "XDG_BIN_HOME"),
            test_data_home: debug_override(lookup, crate::test_support::TEST_DATA_HOME_ENV),
            test_executable_home: debug_override(
                lookup,
                crate::test_support::TEST_EXECUTABLE_HOME_ENV,
            ),
        }
    }
}

/// Abstraction for resolving platform-specific base directories.
///
/// This trait enables dependency injection for directory resolution,
/// allowing tests to use mock implementations that don't touch the
/// real filesystem.
///
/// # Examples
///
/// ```no_run
/// use whitaker_installer::dirs::{BaseDirs, SystemBaseDirs};
///
/// let dirs = SystemBaseDirs::new().expect("failed to initialize directories");
/// if let Some(bin_dir) = dirs.executables() {
///     println!("Executables go in: {}", bin_dir.display());
/// }
/// ```
#[cfg_attr(test, mockall::automock)]
pub trait BaseDirs {
    /// Returns the user's home directory.
    ///
    /// - Unix: `$HOME` or `/home/<user>`
    /// - Windows: `%USERPROFILE%` or `C:\Users\<user>`
    fn home(&self) -> Option<PathBuf>;

    /// Returns the directory for user executables.
    ///
    /// On Unix, respects `XDG_BIN_HOME` if set, otherwise falls back to
    /// `~/.local/bin`. On Windows, returns `~/.local/bin`. This follows the
    /// XDG Base Directory Specification convention. Debug builds of
    /// [`SystemBaseDirs`] honour
    /// [`crate::test_support::TEST_EXECUTABLE_HOME_ENV`] first, so an
    /// integration test can inspect the directory the binary actually used.
    fn executables(&self) -> Option<PathBuf>;

    /// Returns the directory for cloning the Whitaker repository.
    ///
    /// - Linux: `~/.local/share/whitaker`
    /// - macOS: `~/Library/Application Support/whitaker`
    /// - Windows: `%LOCALAPPDATA%\whitaker`
    fn whitaker_data(&self) -> Option<PathBuf>;

    /// Returns the directory holding the installed Dylint bootstrap.
    ///
    /// It sits beside [`Self::whitaker_data`], never inside it, because
    /// that directory is itself the managed Git clone. On Linux this is
    /// `$XDG_DATA_HOME/whitaker-bootstrap`, falling back to
    /// `~/.local/share/whitaker-bootstrap`.
    fn bootstrap_dir(&self) -> Option<PathBuf> {
        self.whitaker_data().and_then(|data_dir| {
            data_dir
                .parent()
                .map(|root| root.join("whitaker-bootstrap"))
        })
    }
}

/// Real implementation of [`BaseDirs`] using the `directories-next` crate.
///
/// This implementation resolves actual platform-specific directories
/// and should be used in production code. It wraps `directories_next::UserDirs`
/// and `directories_next::ProjectDirs` to provide consistent cross-platform
/// directory resolution.
///
/// Debug builds honour [`crate::test_support::TEST_DATA_HOME_ENV`] for
/// [`BaseDirs::whitaker_data`] and
/// [`crate::test_support::TEST_EXECUTABLE_HOME_ENV`] for
/// [`BaseDirs::executables`], so an integration test that drives the binary
/// can keep the installation record and the executable directory in its own
/// temporary tree on platforms whose directories come from APIs that ignore
/// `XDG_DATA_HOME` and `XDG_BIN_HOME`. Release builds ignore both variables.
///
/// # Examples
///
/// ```no_run
/// use whitaker_installer::dirs::{BaseDirs, SystemBaseDirs};
///
/// let dirs = SystemBaseDirs::new().expect("failed to initialize directories");
/// let data_dir = dirs
///     .whitaker_data()
///     .expect("could not determine data directory");
/// println!("Whitaker data at: {}", data_dir.display());
/// ```
#[derive(Debug, Clone)]
pub struct SystemBaseDirs {
    user_dirs: directories_next::UserDirs,
    project_dirs: directories_next::ProjectDirs,
    overrides: DirOverrides,
}

impl SystemBaseDirs {
    /// Creates a new `SystemBaseDirs` instance.
    ///
    /// Returns `None` if the platform's directory conventions cannot be
    /// determined (e.g., on unsupported platforms or when environment
    /// variables are not set correctly).
    #[must_use]
    pub fn new() -> Option<Self> { Self::with_lookup(|variable| std::env::var_os(variable)) }

    /// Creates an instance that reads its overrides through `lookup`.
    ///
    /// `lookup` stands in for the process environment, so a test can supply
    /// a map rather than mutate global state.
    fn with_lookup(lookup: impl Fn(&str) -> Option<OsString>) -> Option<Self> {
        let user_dirs = directories_next::UserDirs::new()?;
        let project_dirs = directories_next::ProjectDirs::from("io", "github", "whitaker")?;
        Some(Self {
            user_dirs,
            project_dirs,
            overrides: DirOverrides::read(&lookup),
        })
    }
}

impl BaseDirs for SystemBaseDirs {
    fn home(&self) -> Option<PathBuf> { Some(self.user_dirs.home_dir().to_owned()) }

    fn executables(&self) -> Option<PathBuf> {
        if let Some(path) = self.overrides.test_executable_home.clone() {
            return Some(path);
        }
        #[cfg(unix)]
        if let Some(path) = self.overrides.xdg_bin_home.clone() {
            return Some(path);
        }
        self.home().map(|h| h.join(".local").join("bin"))
    }

    fn whitaker_data(&self) -> Option<PathBuf> {
        self.overrides
            .test_data_home
            .clone()
            .or_else(|| Some(self.project_dirs.data_dir().to_owned()))
    }
}

#[cfg(test)]
mod tests {
    //! Tests for base-directory resolution.

    use rstest::rstest;

    use super::*;

    #[test]
    fn system_base_dirs_returns_some_on_supported_platforms() {
        let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");

        assert!(dirs.home().is_some(), "expected home_dir to return Some");
    }

    #[test]
    fn whitaker_data_dir_contains_whitaker() {
        let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
        let data_dir = dirs.whitaker_data();

        assert!(
            data_dir.is_some(),
            "expected whitaker_data_dir to return Some"
        );
        assert!(
            data_dir
                .as_ref()
                .is_some_and(|p| p.to_string_lossy().contains("whitaker")),
            "expected path to contain 'whitaker'"
        );
    }

    #[test]
    fn bootstrap_dir_sits_beside_the_managed_clone() {
        let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
        let data_dir = dirs.whitaker_data().expect("data dir");
        let bootstrap = dirs.bootstrap_dir().expect("bootstrap dir");

        assert_eq!(bootstrap.parent(), data_dir.parent());
        assert!(
            !bootstrap.starts_with(&data_dir),
            "never inside the Git clone"
        );
    }

    /// A [`BaseDirs`] whose data directory is fixed, to exercise the default
    /// `bootstrap_dir` without consulting the platform.
    struct FixedDataDir(PathBuf);

    impl BaseDirs for FixedDataDir {
        fn home(&self) -> Option<PathBuf> { None }

        fn executables(&self) -> Option<PathBuf> { None }

        fn whitaker_data(&self) -> Option<PathBuf> { Some(self.0.clone()) }
    }

    #[test]
    fn bootstrap_dir_is_a_sibling_of_the_data_dir() {
        let dirs = FixedDataDir(PathBuf::from("/custom/share/whitaker"));

        assert_eq!(
            dirs.bootstrap_dir(),
            Some(PathBuf::from("/custom/share/whitaker-bootstrap"))
        );
    }

    /// Build [`SystemBaseDirs`] from a fixed set of variables, leaving the
    /// process environment alone.
    fn dirs_with(variables: &[(&str, OsString)]) -> SystemBaseDirs {
        SystemBaseDirs::with_lookup(|name| {
            variables
                .iter()
                .find(|(key, _)| *key == name)
                .map(|(_, value)| value.clone())
        })
        .expect("failed to create SystemBaseDirs")
    }

    /// Which debug-only directory override a case exercises.
    #[derive(Debug, Clone, Copy)]
    enum HomeOverride {
        Data,
        Executables,
    }

    impl HomeOverride {
        /// Return the variable that overrides this directory.
        fn variable(self) -> &'static str {
            match self {
                Self::Data => crate::test_support::TEST_DATA_HOME_ENV,
                Self::Executables => crate::test_support::TEST_EXECUTABLE_HOME_ENV,
            }
        }

        /// Resolve this directory through the production accessor.
        fn resolve(self, dirs: &SystemBaseDirs) -> Option<PathBuf> {
            match self {
                Self::Data => dirs.whitaker_data(),
                Self::Executables => dirs.executables(),
            }
        }
    }

    #[cfg(debug_assertions)]
    #[rstest]
    #[case::data_home(HomeOverride::Data, "whitaker-test-data-home")]
    #[case::executable_home(HomeOverride::Executables, "whitaker-test-executable-home")]
    fn debug_builds_honour_the_home_overrides(
        #[case] target: HomeOverride,
        #[case] dir_name: &str,
    ) {
        let override_root = std::env::temp_dir().join(dir_name);
        let dirs = dirs_with(&[(target.variable(), override_root.clone().into_os_string())]);

        assert_eq!(target.resolve(&dirs), Some(override_root));
    }

    #[cfg(debug_assertions)]
    #[rstest]
    #[case::data_home(HomeOverride::Data, "relative/data")]
    #[case::executable_home(HomeOverride::Executables, "relative/bin")]
    fn a_relative_home_override_is_ignored(#[case] target: HomeOverride, #[case] relative: &str) {
        let dirs = dirs_with(&[(target.variable(), OsString::from(relative))]);
        let resolved = target.resolve(&dirs).expect("resolved directory");

        assert!(
            resolved.is_absolute(),
            "a relative override must not replace the platform directory"
        );
    }

    #[cfg(unix)]
    #[rstest]
    #[case::unset(None)]
    #[case::relative(Some("relative/path"))]
    fn bin_dir_falls_back_to_local_bin(#[case] xdg_bin_home: Option<&str>) {
        let variables: Vec<(&str, OsString)> = xdg_bin_home
            .map(|value| ("XDG_BIN_HOME", OsString::from(value)))
            .into_iter()
            .collect();
        let dirs = dirs_with(&variables);
        let bin_dir = dirs.executables().expect("expected bin_dir to return Some");

        assert!(
            bin_dir.to_string_lossy().contains(".local"),
            "expected the fallback path to contain '.local', got {bin_dir:?}"
        );
    }

    #[cfg(unix)]
    #[test]
    fn bin_dir_respects_xdg_bin_home() {
        let dirs = dirs_with(&[("XDG_BIN_HOME", OsString::from("/custom/bin"))]);
        let bin_dir = dirs.executables().expect("expected bin_dir to return Some");

        assert_eq!(bin_dir, PathBuf::from("/custom/bin"));
    }
}
